beforeExample:
class MyClass {
    public void myMethod(String next, String trigger) {
        String result = next.toLowerCase().equals(trigger) ? "TRUE" : "FALSE";
        System.out.println(result);
    }
}

afterExample:
class MyClass {
    public void myMethod(String next, String trigger) {
        String result = next.equalsIgnoreCase(trigger) ? "TRUE" : "FALSE";
        System.out.println(result);
    }
}

negativeExample:
class MyClass {
    public void myMethod(String next, String trigger) {
        // Not replaced: toLowerCase() is on the argument of equals()
        String result1 = next.equals(trigger.toLowerCase()) ? "TRUE" : "FALSE";
        System.out.println(result1);

        // Not replaced: toLowerCase() is not followed by equals()
        String result2 = next.toLowerCase().startsWith(trigger) ? "TRUE" : "FALSE";
        System.out.println(result2);
    }
}
